/**
 * Icônes dessinées pour EventMaster : formes pleines, découpes et un second ton
 * (la couleur du texte à 32 % d'opacité). Grille 24 × 24 ; suivent `currentColor`.
 * Les noms sont ceux de `components/icons/index.tsx`, qui retombe sur Phosphor pour les icônes non dessinées.
 */
import type { ReactNode, SVGProps } from 'react';

export type CustomIconProps = Omit<SVGProps<SVGSVGElement>, 'ref'> & {
  size?: number | string;
  /** Variante pleine (classe `fill-…` posée par l'appelant). */
  solid?: boolean;
};

function frame(children: ReactNode, { size = 24, solid: _solid, ...props }: CustomIconProps) {
  void _solid;
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="none" aria-hidden="true" focusable="false" {...props}>
      {children}
    </svg>
  );
}

